-- TRAFFICRIDER(AU.01)[32+64]-V13
-- Do not edit this file. Any change breaks the decoder.
local _usbqrc = 87
local _zszdqn = 138
local _wlwlxr = 248
local _pulfbu = ""

local _bzzrjv = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _hpiffs(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _jvbhsk(d)
	d = d:gsub("[^" .. _bzzrjv .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_bzzrjv:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _zrmvib = _jvbhsk(_pulfbu)
local _lmocrl = { _usbqrc, _zszdqn, _wlwlxr }
local _pxhwyd = {}
for i = 1, #_zrmvib do
	_pxhwyd[i] = string.char(_hpiffs(_zrmvib:byte(i), _lmocrl[(i - 1) % 3 + 1]))
end

local _qbmbel = load or loadstring
local _kbnuke, _dildiw = _qbmbel(table.concat(_pxhwyd), "=w")
if not _kbnuke then
	gg.alert("Corrupted file: " .. tostring(_dildiw))
	os.exit()
end
_kbnuke()
